import{_ as s,o as t,c as a,a7 as i}from"./chunks/framework.CWfAgRyf.js";const u=JSON.parse('{"title":"Basic usage","description":"How to start and stop an Axolotl-PM server, use the setup wizard, and keep the server running in the background on Linux or macOS with screen.","frontmatter":{"title":"Basic usage","outline":"deep","description":"How to start and stop an Axolotl-PM server, use the setup wizard, and keep the server running in the background on Linux or macOS with screen.","head":[["link",{"rel":"canonical","href":"https://axolotl-pm.org/docs/basic-usage"}]]},"headers":[],"relativePath":"docs/basic-usage.md","filePath":"docs/basic-usage.md","lastUpdated":null}'),n={name:"docs/basic-usage.md"};function o(r,e,c,l,h,p){return t(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="basic-usage" tabindex="-1">Basic usage <a class="header-anchor" href="#basic-usage" aria-label="Permalink to &quot;Basic usage&quot;">​</a></h1><h2 id="starting-the-server" tabindex="-1">Starting the server <a class="header-anchor" href="#starting-the-server" aria-label="Permalink to &quot;Starting the server&quot;">​</a></h2><ul><li>Linux/MacOS: run <code>./start.sh</code></li><li>Windows: Double-click <code>start.cmd</code>, or open PowerShell in the server directory and run <code>.\\start.ps1</code>.</li></ul><h2 id="setup-wizard" tabindex="-1">Setup Wizard <a class="header-anchor" href="#setup-wizard" aria-label="Permalink to &quot;Setup Wizard&quot;">​</a></h2><p>The first time Axolotl-PM starts, it launches a setup wizard.</p><p>The setup wizard will allow you to choose a language, and guide you through setting up basic information about your new server, like its name, the server port, etc.</p><div class="info custom-block"><p class="custom-block-title">Note</p><p>You’ll be asked to accept the terms of Axolotl-PM’s license. You can read the full text of the license on <a href="https://github.com/axolotl-pm/PocketMine-MP/blob/master/LICENSE" target="_blank" rel="noreferrer">GitHub</a>.</p></div><div class="tip custom-block"><p class="custom-block-title">Tip</p><p>You can skip the setup wizard by passing <code>--no-wizard</code> to <code>start.sh</code>, <code>start.cmd</code> or <code>start.ps1</code>.</p></div><h2 id="stopping-the-server" tabindex="-1">Stopping the server <a class="header-anchor" href="#stopping-the-server" aria-label="Permalink to &quot;Stopping the server&quot;">​</a></h2><p>To stop the server, simply type <code>stop</code> in the console and press enter.</p><div class="danger custom-block"><p class="custom-block-title">Error</p><p>Do NOT click the X to stop the server. You could lose data or your data might get corrupted.</p></div><h2 id="running-the-server-in-the-background-linux-macos-only" tabindex="-1">Running the server in the background (Linux/MacOS only) <a class="header-anchor" href="#running-the-server-in-the-background-linux-macos-only" aria-label="Permalink to &quot;Running the server in the background (Linux/MacOS only)&quot;">​</a></h2><p>If you’re using a VPS to host Axolotl-PM, you’ll probably want to be able to run the server in the background so that you can keep using your shell, and also be able to get back into the server console later on when reconnecting to the host.</p><p>For this purpose, we recommend using the <code>screen</code> command. You can usually install it using your OS’s package manager (e.g. <code>apt</code>) if you don’t have it installed.</p><h3 id="starting-a-screen-for-a-new-server-instance" tabindex="-1">Starting a screen for a new server instance <a class="header-anchor" href="#starting-a-screen-for-a-new-server-instance" aria-label="Permalink to &quot;Starting a screen for a new server instance&quot;">​</a></h3><p>To create a new screen, <code>cd</code> into the server folder and run the following:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">screen</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -S</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pocketmine</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">Tip</p><p>You can change <code>pocketmine</code> to anything you want. This is just an identifier for the screen so you can get back to it later.</p><p>If you want to run multiple Axolotl-PM instances, you’ll want to start multiple screens and give each one a different identifier.</p></div><p>Once inside the screen, you can run <code>./start.sh</code> as normal.</p><h3 id="putting-the-server-in-the-background" tabindex="-1">Putting the server in the background <a class="header-anchor" href="#putting-the-server-in-the-background" aria-label="Permalink to &quot;Putting the server in the background&quot;">​</a></h3><p>To get out of the screen and put the server in the background, press <code>Ctrl a</code> <code>Ctrl d</code>. You’ll see a message like this:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[detached from 395586.pocketmine]</span></span></code></pre></div><h3 id="opening-the-console-of-a-server-running-in-the-background" tabindex="-1">Opening the console of a server running in the background <a class="header-anchor" href="#opening-the-console-of-a-server-running-in-the-background" aria-label="Permalink to &quot;Opening the console of a server running in the background&quot;">​</a></h3><p>To get back to the console of a server you’ve already started:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">screen</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pocketmine</span></span></code></pre></div><p>Replace <code>pocketmine</code> with the name you gave to the <code>-S</code> flag when creating the screen.</p><div class="tip custom-block"><p class="custom-block-title">Tip</p><p>This command may not work if your SSH connection was interrupted, or if another user is viewing the screen in another shell.</p><p>If you need to forcibly take control of the screen, try using <code>screen -D -RR &lt;screen name&gt;</code> instead.</p></div><h3 id="listing-active-screens" tabindex="-1">Listing active screens <a class="header-anchor" href="#listing-active-screens" aria-label="Permalink to &quot;Listing active screens&quot;">​</a></h3><p>If you can’t remember the name of your screen and/or have multiple screens (e.g. with multiple running servers):</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">screen</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -ls</span></span></code></pre></div><p>This will output something like:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">There</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> is</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> a</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> screen</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> on:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">     395586.pocketmine</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">       (11/22/25 </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">19:13:05</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)     (</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Detached</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">1</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Socket</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> in</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /run/screen/S-user.</span></span></code></pre></div><p>In this example, we would be able to reconnect to the screen using <code>screen -r 395586.pocketmine</code> or <code>screen -r pocketmine</code>.</p><h3 id="closing-the-screen-after-stopping-the-server" tabindex="-1">Closing the screen after stopping the server <a class="header-anchor" href="#closing-the-screen-after-stopping-the-server" aria-label="Permalink to &quot;Closing the screen after stopping the server&quot;">​</a></h3><p>You can close the screen by typing <code>exit</code> inside it, the same as you would for a normal shell.</p>`,35)])])}const g=s(n,[["render",o]]);export{u as __pageData,g as default};
